/**
 * Replays the Rust golden fixtures through the compiled wasm.
 *
 * The fixtures are generated by `cargo test -p vlo-kernel` from the same `api` module
 * the wasm exports wrap, so any difference here means the committed `wasm/` drifted
 * from the Rust source — rebuild with `scripts/build-kernel.sh`.
 */

import { readFileSync, readdirSync } from "node:fs";
import { describe, expect, it } from "vitest";

import { loadKernel } from "./load.ts";
import { PROTOCOL_VERSION, START_STEP_ID, type EventInput, type RunRef } from "./protocol.ts";

const FIXTURES_DIR = new URL("../../../../../fixtures/kernel/", import.meta.url);

interface Fixture {
  export: string;
  input: unknown;
  output: unknown;
}

const fixtures = readdirSync(FIXTURES_DIR)
  .filter((name) => name.endsWith(".json"))
  .sort()
  .map((name) => ({
    name,
    ...(JSON.parse(readFileSync(new URL(name, FIXTURES_DIR), "utf8")) as Fixture),
  }));

const kernel = await loadKernel();
const wasm = await import("../../wasm/vlo_kernel.js");

const exports: Record<string, (input: string) => string> = {
  kernel_version: () => wasm.kernel_version(),
  validate_event: wasm.validate_event,
  prepare_event: wasm.prepare_event,
  reduce_step: wasm.reduce_step,
  compute_state_hash: wasm.compute_state_hash,
  plan_retry: wasm.plan_retry,
  refold_check: wasm.refold_check,
  derive_ids: wasm.derive_ids,
};

const RANDOM = "9f86d081884c7d659a2feaa0c55ad015";

function startedEvent(runId: string, input: unknown): EventInput {
  return {
    run_id: runId,
    step_id: START_STEP_ID,
    attempt: 0,
    kind: "marker",
    status: "succeeded",
    ts_ms: 1_700_000_000_000,
    random: RANDOM,
    payload: JSON.stringify(input),
  };
}

function runRef(runId: string): RunRef {
  return {
    run_id: runId,
    workflow: "example",
    bundle_digest: "sha256:bundle",
    status: "created",
    last_seq: 0,
  };
}

describe("kernel", () => {
  it("reports a version this SDK can speak", () => {
    const version = kernel.version();
    expect(version.protocol).toBe(PROTOCOL_VERSION);
    expect(version.version).toMatch(/^\d+\.\d+\.\d+$/);
    expect(version.features).toContain("state_hash_v1");
  });

  it("found the committed fixtures", () => {
    expect(fixtures.length).toBeGreaterThan(20);
    const covered = new Set(fixtures.map((fixture) => fixture.export));
    expect([...covered].sort()).toEqual(Object.keys(exports).sort());
  });

  it.each(fixtures)("replays $name", (fixture) => {
    const exported = exports[fixture.export];
    expect(exported, `unknown export ${fixture.export}`).toBeDefined();
    const output: unknown = JSON.parse(exported!(JSON.stringify(fixture.input)));
    expect(output).toEqual(fixture.output);
  });
});

describe("kernel interface", () => {
  it("folds a started event into a transition", () => {
    const run = runRef("run_ts");
    const event = startedEvent("run_ts", { n: 2 });

    const prepared = kernel.prepareEvent({ run, event });
    expect(prepared.ok).toBe(true);
    if (!prepared.ok || prepared.value.mode !== "reduce") throw new Error("expected a reduce");
    expect(prepared.value.init_input).toEqual({ n: 2 });

    const reduced = kernel.reduceStep({
      run,
      kernel_state: prepared.value.kernel_state,
      event,
      reduction: {
        state: JSON.stringify({ phase: "work" }),
        commands: [{ type: "task", activity: "plan", input: { a: 1 } }],
      },
    });
    if (!reduced.ok) throw new Error(reduced.error.message);
    expect(reduced.value.run.status).toBe("running");
    expect(reduced.value.tasks).toHaveLength(1);
    expect(reduced.value.tasks[0]?.idempotency_key).toBe("run_ts:task#1:1");
    expect(reduced.value.events.map((e) => e.seq)).toEqual([1, 2]);
    expect(reduced.value.events.every((e) => e.state_hash === reduced.value.state_hash)).toBe(true);
  });

  it("returns errors as values, never as exceptions", () => {
    const result = kernel.prepareEvent({
      run: { ...runRef("run_ts"), status: "completed", last_seq: 9 },
      event: startedEvent("run_ts", null),
    });
    expect(result.ok).toBe(false);
    if (result.ok) throw new Error("expected a rejection");
    expect(result.error.code).toBe("run_closed");
  });

  it("agrees with itself on state hashing, ids and retry planning", () => {
    const kernelState = {
      v: 1,
      status: "running" as const,
      step_no: 0,
      steps: {},
      closed_steps: 0,
      usage_total: { cpu_ms: 0, tokens: 0, cost_micro_usd: 0 },
    };
    const sorted = kernel.stateHash({ kernel_state: kernelState, state: '{"a":1,"b":2}' });
    const unsorted = kernel.stateHash({ kernel_state: kernelState, state: '{ "b": 2, "a": 1 }' });
    if (!sorted.ok || !unsorted.ok) throw new Error("expected hashes");
    expect(sorted.value.hash).toBe(unsorted.value.hash);

    const ids = kernel.deriveIds({ run_id: "run_ts", step_id: "task#1", attempt: 2 });
    if (!ids.ok) throw new Error("expected ids");
    expect(ids.value.task_id).toBe("run_ts:task#1");
    expect(ids.value.idempotency_key).toBe("run_ts:task#1:2");

    const stop = kernel.planRetry({
      policy: {
        max_attempts: 3,
        backoff: "exponential",
        initial_ms: 1000,
        max_ms: 600_000,
        factor: 2,
        jitter: "full",
      },
      attempt: 1,
      cause: "schema_violation",
      random: RANDOM,
    });
    if (!stop.ok) throw new Error("expected a plan");
    expect(stop.value.retry).toBe(false);
  });

  it("is memoised", async () => {
    expect(await loadKernel()).toBe(kernel);
  });
});
